import base64,hashlib,json,lzma,zlib
def decode92(data):
 alphabet='!#$%&()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{|}~\\';buffer=bits=0;value=-1;output=bytearray()
 for char in data:
  digit=alphabet.index(char)
  if value<0:value=digit
  else:
   value+=digit*92;buffer|=value<<bits;bits+=13 if (value&8191)>271 else 14
   while bits>7:output.append(buffer&255);buffer>>=8;bits-=8
   value=-1
 if value>=0:output.append((buffer|value<<bits)&255)
 return bytes(output)
